Set-Location -LiteralPath $PSScriptRoot
$msg = 'compose: the composer must not advertise a link the send path strips. After the no-URL-in-SMS rule landed, the preview endpoint still minted and returned a booking_url, and the composer rendered WILL BE SENT AS <url> directly above a body containing no link at all - the interface contradicting the code, which is exactly the class of thing that must never be displayed unless the backend can verify it. Both compose endpoints now publish sms_content_policy.policy_report(), no preview token is minted while links are off, the Include booking link checkbox is hidden rather than offered, and the panel says plainly that texts carry no links and the scheduling link goes by email. The frontend also had its own client-side preview that appended the URL independently - a second place the body was assembled, now reflecting the same rule so preview and send cannot diverge. Email untouched.'
& "$PSScriptRoot\deploy.ps1" -Message $msg
Write-Output ("DEPLOY_EXIT=" + $LASTEXITCODE)
